//
// The version strings are generated by CMake, so these tests are really testing
// the build's configure step as much as the C++: a template placeholder that
// fails to expand, or a version that stops matching the project's, shows up here
// rather than in a user's bug report.

#include "common/Version.h"

#include "common/VersionInfo.h"

#include <gtest/gtest.h>

#include <string>
#include <string_view>

namespace {

TEST(Version, ReportsANonEmptyVersion) {
    EXPECT_FALSE(enzan::version().empty());
}

TEST(Version, VersionMatchesTheConfiguredValue) {
    EXPECT_EQ(enzan::version(), std::string_view(ENZAN_VERSION_STRING));
}

TEST(Version, VersionStartsWithTheNumericComponents) {
    const std::string expectedPrefix = std::to_string(ENZAN_VERSION_MAJOR) + '.'
                                       + std::to_string(ENZAN_VERSION_MINOR) + '.'
                                       + std::to_string(ENZAN_VERSION_PATCH);
    EXPECT_TRUE(enzan::version().starts_with(expectedPrefix))
        << "version() is '" << enzan::version() << "', expected it to start with '"
        << expectedPrefix << '\'';
}

TEST(Version, NoTemplatePlaceholderSurvivedConfiguration) {
    // An unexpanded @VAR@ placeholder is the characteristic failure of a
    // configure_file that was given the wrong substitution mode.
    EXPECT_EQ(enzan::version().find('@'), std::string_view::npos);
    EXPECT_EQ(enzan::sourceRevision().find('@'), std::string_view::npos);
    EXPECT_EQ(enzan::buildDescription().find('@'), std::string::npos);
}

TEST(Version, SourceRevisionIsAlwaysPopulated) {
    // Outside a git checkout the value is the literal "unknown" rather than an
    // empty string, so that consumers never have to special-case emptiness.
    EXPECT_FALSE(enzan::sourceRevision().empty());
}

TEST(Version, VersionLineHasTheDocumentedShape) {
    const std::string line = enzan::versionLine();

    EXPECT_TRUE(line.starts_with("enzan ")) << "versionLine() is '" << line << '\'';
    EXPECT_NE(line.find(enzan::version()), std::string::npos);
    EXPECT_NE(line.find(enzan::sourceRevision()), std::string::npos);
    EXPECT_EQ(line.find('\n'), std::string::npos) << "versionLine() must be a single line";
}

TEST(Version, BuildDescriptionNamesTheCompilerAndBuildType) {
    const std::string description = enzan::buildDescription();

    EXPECT_NE(description.find("Compiler:"), std::string::npos);
    EXPECT_NE(description.find("Build type:"), std::string::npos);
    EXPECT_NE(description.find("Optional components:"), std::string::npos);
    EXPECT_TRUE(description.ends_with("\n")) << "description is '" << description << '\'';
}

TEST(Version, BuildDescriptionAgreesWithTheFeatureMacros) {
    const std::string description = enzan::buildDescription();

#ifdef ENZAN_WITH_SYSTEMVERILOG
    EXPECT_NE(description.find("systemverilog"), std::string::npos);
#else
    EXPECT_EQ(description.find("systemverilog"), std::string::npos);
#endif

#if !defined(ENZAN_WITH_SYSTEMVERILOG) && !defined(ENZAN_WITH_VHDL) && !defined(ENZAN_WITH_TCL) \
    && !defined(ENZAN_WITH_JIT) && !defined(ENZAN_WITH_SANITIZERS)
    EXPECT_NE(description.find("Optional components: none"), std::string::npos);
#endif
}

} // namespace
